class Solution {
public:
    long long countXorSubarrays(vector<int>& nums, int k) {
        const int B = 30;
        vector<array<int,2>> ch(1, {0, 0});
        vector<int> ct(1, 0);
        auto ins = [&](int x) {
            int node = 0;
            for (int b = B - 1; b >= 0; b--) {
                int d = (x >> b) & 1;
                if (!ch[node][d]) { ch.push_back({0, 0}); ct.push_back(0); ch[node][d] = ch.size() - 1; }
                node = ch[node][d]; ct[node]++;
            }
        };
        ins(0);
        long long ans = 0; int cur = 0;
        for (int x : nums) {
            cur ^= x;
            int node = 0; bool full = true;
            for (int b = B - 1; b >= 0; b--) {
                int cb = (cur >> b) & 1;
                if ((k >> b) & 1) {
                    node = ch[node][cb ^ 1];
                    if (!node) { full = false; break; }
                } else {
                    ans += ct[ch[node][cb ^ 1]];
                    node = ch[node][cb];
                    if (!node) { full = false; break; }
                }
            }
            if (full) ans += ct[node];
            ins(cur);
        }
        return ans;
    }
};

