class Solution {
    public long countXorSubarrays(int[] nums, int k) {
        final int B = 30;
        List<int[]> ch = new ArrayList<>();
        List<Integer> ct = new ArrayList<>();
        ch.add(new int[]{0, 0}); ct.add(0);
        java.util.function.IntConsumer ins = x -> {
            int node = 0;
            for (int b = B - 1; b >= 0; b--) {
                int d = (x >> b) & 1;
                if (ch.get(node)[d] == 0) { ch.add(new int[]{0, 0}); ct.add(0); ch.get(node)[d] = ch.size() - 1; }
                node = ch.get(node)[d]; ct.set(node, ct.get(node) + 1);
            }
        };
        ins.accept(0);
        long ans = 0; int cur = 0;
        for (int x : nums) {
            cur ^= x;
            int node = 0; boolean full = true;
            for (int b = B - 1; b >= 0; b--) {
                int cb = (cur >> b) & 1;
                if (((k >> b) & 1) == 1) {
                    node = ch.get(node)[cb ^ 1];
                    if (node == 0) { full = false; break; }
                } else {
                    ans += ct.get(ch.get(node)[cb ^ 1]);
                    node = ch.get(node)[cb];
                    if (node == 0) { full = false; break; }
                }
            }
            if (full) ans += ct.get(node);
            ins.accept(cur);
        }
        return ans;
    }
}

