class Solution:
    def countXorSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums); ans = 0
        for j in range(n):
            x = 0
            for i in range(j, -1, -1):
                x ^= nums[i]
                if x >= k: ans += 1
        return ans

